 fn format_uptime(seconds: u64) -> String {
     let h = seconds / 3600;
     let m = (seconds % 3600) / 60;
     let s = seconds % 60;
     if h > 0 {
         format!("{h}h {m}m")
     } else if m > 0 {
         format!("{m}m {s}s")
     } else {
         format!("{s}s")
     }
 }

 fn format_ms(ms: u64) -> String {
     if ms >= 1000 {
         format!("{:.1}s", ms as f64 / 1000.0)
     } else {
         format!("{ms}ms")
     }
 }

